namespace PZ3D {
 sealed partial class MainForm {
  string HelpBody(int index){if(index==0)return LauncherQuickHelp+"\r\n\r\n"+ReticleHelp+"\r\n\r\n"+ComponentHelp;if(index==1||index==6)return ReticleHelp+"\r\n\r\n"+ComponentHelp;if(index==2)return "额外 3D 物件模型\r\n\r\n用于将家具、家电、栅栏等平面物件替换成立体模型，不是光影，也不是基础视角的必需项。勾选额外 3D 物件模型并点击“安装”，自动下载所需内容并启用。\r\n\r\n不需要时，只勾选此项并点击“卸载”，保留基础视角和下载文件。\r\n\r\n工坊3810302175，原模型作者 sour_kisel。";return HelpContent.Bodies[index-1].Replace("安装 / 启用 3D","安装").Replace("关闭 3D + Buddy","卸载（勾选基础 3D）")+(index==8?LegalContent.OptionalCredits:"");}
  const string LauncherQuickHelp="OZL 原生界面使用说明\r\n\r\n在主界面勾选要操作的组件，再点击“安装”“卸载”或“检查更新”。安装后通过 Steam 启动游戏。\r\n\r\n“光影列表”选择或导入光影；“Viewpoint 中文设置”调整画面参数与快捷键。\r\n\r\n“启动与内存”修改 Java 启动内存，“维护与诊断”清理多人地图缓存或重下载工坊文件。当前任务的进度和结果在界面下方显示。\r\n\r\n原生界面更新程序时，下载新版安装包或免安装包，再退出并更新程序文件。个人存档与启动器数据保留。";
  const string ComponentHelp="组件安装与使用\r\n\r\n1. 勾选需要的基础 3D、物件、枪械或汉化，点击“安装”。完成 Java 授权后重启游戏，按 O 开关第一人称，Shift+O 切换第一／第三人称。\r\n\r\n2. 第一人称枪械：安装作者 Shoot to Thrill 组件。联机服务器需启用 ShootToThrillMultiplayer。右键瞄准，Ctrl+V 切换腰射／精瞄；自定义键位在游戏设置中查看。枪械内容包需另外安装。\r\n\r\n3. 游戏内中文：安装老余汉化，游戏语言选择简体中文；首次允许 laoyu.javacn / LaoYuTranslationJava.jar 后重启游戏。\r\n\r\n4. 卸载时只勾选要撤销的组件，再点击“卸载”；卸载基础 3D 会连带关闭依赖组件。保留下载文件、光影与存档。\r\n\r\n5. 勾选内容后点击“检查更新”；Java 文件更新后如出现授权提示，重新允许该文件。\r\n\r\n作者工坊：Viewpoint 3809306528（ellu/norkus）；ZombieBuddy 3619862853；汉化 3810637496（老余）；射击 3813032735（haru）。";
 }
}
